import {BrowserProvider,JsonRpcProvider,Contract,parseEther,formatEther,isAddress} from './ethers.min.js';
const $=id=>document.getElementById(id), bytes=s=>new TextEncoder().encode(s).length, short=s=>s.slice(0,6)+'…'+s.slice(-4);
const abi=['function tip(string name,string note) payable','function beneficiary() view returns(address)','function tipCount() view returns(uint256)','function totalTipped() view returns(uint256)','function getTips(uint256 offset,uint256 limit) view returns(tuple(address supporter,uint256 amount,uint64 timestamp,string name,string note)[])','function withdraw()','event TipReceived(uint256 indexed id,address indexed supporter,uint256 amount,string name,string note,uint64 timestamp)'];
let config,reader,board,wallet,account,chain,busy=false,shown=20,refreshing=false,recipient;
const message=s=>{$('status').textContent=s;};
function errorText(e){if(e.code===4001||e.code==='ACTION_REJECTED'||e.info?.error?.code===4001)return 'You declined the wallet request. No new transaction was sent.';if(e.code==='INSUFFICIENT_FUNDS')return 'You need enough Sepolia ETH for the tip and network gas.';if(e.code==='TRANSACTION_REPLACED')return e.cancelled?'Transaction cancelled in your wallet.':'Transaction replaced. Refresh the wall to check the confirmed result.';if(e.code==='CALL_EXCEPTION')return 'The transaction failed. Check your amount and text length, then try again.';return 'Could not complete this request. Check your wallet and connection, then try again.';}
function sync(){ $('connect').textContent=account?short(account)+' ↗':'Connect wallet ↗';$('send').textContent=!account?'Connect wallet to give ↗':chain!==11155111n?'Switch to Sepolia ↗':'Send a little thanks ↗';$('send').disabled=busy;$('withdraw').disabled=busy;$('connect').disabled=busy;$('owner').hidden=!(account&&recipient&&account.toLowerCase()===recipient.toLowerCase());}
async function connect(){if(!window.ethereum){message('Open this page in a wallet browser or install an Ethereum browser wallet to continue.');return;}try{wallet=new BrowserProvider(window.ethereum);await wallet.send('eth_requestAccounts',[]);await readWallet();message(chain===11155111n?'Wallet connected. You’re ready to give.':'Your wallet is on another network. Switch to Sepolia before sending.');}catch(e){message(errorText(e));}}
async function readWallet(){const accounts=await window.ethereum.request({method:'eth_accounts'});account=accounts[0]||null;chain=BigInt(await window.ethereum.request({method:'eth_chainId'}));sync();}
async function switchNetwork(){try{await window.ethereum.request({method:'wallet_switchEthereumChain',params:[{chainId:'0xaa36a7'}]});wallet=new BrowserProvider(window.ethereum);await readWallet();}catch(e){message(e.code===4902?'Add Ethereum Sepolia to your wallet (chain ID 11155111), then reconnect.':errorText(e));}}
function card(t,id){const el=document.createElement('article');el.className='card';const head=document.createElement('div');head.className='card-head';const name=document.createElement('b');name.textContent=t.name||'A grateful commuter';const value=document.createElement('span');value.textContent=formatEther(t.amount)+' ETH';head.append(name,value);const quote=document.createElement('blockquote');quote.textContent=t.note||'A little thanks for keeping us moving.';const foot=document.createElement('div');foot.className='card-foot';const addr=document.createElement('a');addr.href='https://sepolia.etherscan.io/address/'+t.supporter;addr.target='_blank';addr.rel='noopener';addr.textContent=short(t.supporter);const date=document.createElement('span');date.textContent=new Date(Number(t.timestamp)*1000).toLocaleDateString(undefined,{month:'short',day:'numeric'})+' · Record #'+id;foot.append(addr,date);el.append(head,quote,foot);return el;}
async function refresh(minBlock=0){if(!board||refreshing)return;refreshing=true;try{const block=Math.max(typeof minBlock === 'number' ? minBlock : 0,await reader.getBlockNumber());const opts={blockTag:block};const [count,total,balance]=await Promise.all([board.tipCount(opts),board.totalTipped(opts),reader.getBalance(config.address,block)]);const start=Math.max(0,Number(count)-shown);let rows=[];for(let offset=start;offset<Number(count);offset+=50){rows.push(...await board.getTips(offset,Math.min(50,Number(count)-offset),opts));}const fragment=document.createDocumentFragment();rows.map((row,i)=>({row,id:start+i})).reverse().forEach(({row,id})=>fragment.append(card(row,id)));if(rows.length)$('wall').replaceChildren(fragment);else{$('wall').innerHTML='<div class="empty"><span class="empty-mark">✳</span><h3>Be the first to say thanks.</h3><p>Send a tip and your confirmed thank-you will appear here.</p></div>';}$('total').textContent=formatEther(total);$('count').textContent=count.toString();$('balance').textContent=formatEther(balance)+' ETH available';$('more').hidden=start===0;$('live').textContent='● Live from Sepolia';$('read-status').textContent='Verified through block '+block.toLocaleString()+'. Updates every 12 seconds.';}catch{$('live').textContent='○ Connection interrupted';$('read-status').textContent='Could not refresh the ledger. Previously loaded entries may be out of date. Try Refresh.';}finally{refreshing=false;}}
async function transact(kind){if(busy)return;if(!account){await connect();return;}if(chain!==11155111n){await switchNetwork();return;}if(!board){message('The contract has not been deployed yet. Add deployment settings to activate real tips.');return;}let amount;
if(kind==='tip'){try{amount=parseEther($('amount').value.trim());if(amount<=0n)throw Error();}catch{message('Enter a positive ETH amount with at most 18 decimal places.');return;}if(bytes($('name').value)>40||bytes($('note').value)>280){message('Use a name of at most 40 bytes and a note of at most 280 bytes. Emoji may use several bytes.');return;}}
busy=true;sync();$('transaction').hidden=true;try{message('Confirm the transaction in your wallet.');wallet=new BrowserProvider(window.ethereum);const signer=await wallet.getSigner();if((await wallet.getNetwork()).chainId!==11155111n)throw Error('Wrong network');const contract=board.connect(signer);const tx=kind==='tip'?await contract.tip($('name').value,$('note').value,{value:amount}):await contract.withdraw();$('transaction').href='https://sepolia.etherscan.io/tx/'+tx.hash;$('transaction').hidden=false;message('Transaction sent. Waiting for confirmation — your entry is not on the wall yet.');let receipt;try{receipt=await tx.wait(1);}catch(e){if(e.code==='TRANSACTION_REPLACED'&&!e.cancelled&&e.receipt){receipt=e.receipt;$('transaction').href='https://sepolia.etherscan.io/tx/'+receipt.hash;}else throw e;}if(receipt.status!==1)throw {code:'CALL_EXCEPTION'};message(kind==='tip'?'Confirmed! Your thank-you is recorded on-chain.':'Withdrawal confirmed. Funds were sent to the beneficiary.');if(kind==='tip'){$('note').value='';$('bytes').textContent='0 / 280 bytes';shown=20;}await refresh(receipt.blockNumber);}catch(e){message(errorText(e));}finally{busy=false;sync();}}
$('connect').onclick=connect;$('tip-form').onsubmit=e=>{e.preventDefault();transact('tip');};$('withdraw').onclick=()=>transact('withdraw');$('refresh').onclick=refresh;$('more').onclick=()=>{shown+=20;refresh();};$('note').oninput=()=>{$('bytes').textContent=bytes($('note').value)+' / 280 bytes';$('bytes').style.color=bytes($('note').value)>280?'#b03e35':'';};document.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>{$('amount').value=b.dataset.amount;document.querySelectorAll('[data-amount]').forEach(x=>x.classList.toggle('selected',x===b));});$('amount').oninput=()=>document.querySelectorAll('[data-amount]').forEach(x=>x.classList.toggle('selected',x.dataset.amount===$('amount').value));
if(window.ethereum){window.ethereum.on?.('accountsChanged',()=>{readWallet().catch(()=>{account=null;sync();});});window.ethereum.on?.('chainChanged',()=>{wallet=new BrowserProvider(window.ethereum);readWallet().catch(()=>{});});window.ethereum.on?.('disconnect',()=>{account=null;sync();});}
try{config=await (await fetch('./config.json')).json();if(config.chainId!==11155111)throw Error();if(config.address&&isAddress(config.address)){reader=new JsonRpcProvider(config.rpcUrl);if((await reader.getNetwork()).chainId!==11155111n)throw Error();if(await reader.getCode(config.address)==='0x')throw Error();board=new Contract(config.address,abi,reader);recipient=await board.beneficiary();$('contract-link').href='https://sepolia.etherscan.io/address/'+config.address+'#code';$('contract-link').hidden=false;await refresh();setInterval(refresh,12000);}else{$('read-status').textContent='Deployment pending. No funds can be sent until a Sepolia contract is configured.';}sync();}catch{$('read-status').textContent='Could not load or validate the Sepolia contract. Check configuration and refresh.';}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_praise_board',description:'Read the current confirmed supporter count and total from the visible board. Does not send a transaction.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(Object.keys(input).length)throw Error('No arguments expected');await refresh();return {count:$('count').textContent,totalETH:$('total').textContent,status:$('read-status').textContent};}});}catch{}}

